    let input: Vec<Complex> = (0..8)
        .map(|i| Complex { real: i as f32, imag: 0.0 })
        .collect();

    let mut inplace = input.clone();
    fft::rader_inplace(&mut inplace, 3);

    let mut out_of_place = vec![Complex { real: 0.0, imag: 0.0 }; 8];
    fft::rader(&input, &mut out_of_place, 3);

